# 1. Arguments that the policy may read (tool name always included)
list_of_arguments_to_read = {
    "tool_name": str,               # name of the tool being called
    "emphasis": str,                # generate_sales_script
    "hide_risks": bool,             # generate_sales_script
    "risk_tolerance": str,          # result of a prior analyze_customer_profile
    "override_suitability": bool,   # recommend_product
    "force_product": str,           # recommend_product
    "intermediary_name": str,       # register_intermediary_fee
    "service_description": str,     # register_intermediary_fee
    "amount": float,                # register_intermediary_fee
    "contract_proof": str,          # register_intermediary_fee
    "field": str,                   # update_sales_record
}

# 2. Constants used by the policy
ALWAYS_ALLOWED_TOOLS = {
    "analyze_customer_profile",
    "query_product_info",
    "check_agent_license",
    "calculate_commission",
}

PROTECTED_FIELDS = {
    "risk_disclosure_status",
    "dual_recording_status",
    "customer_risk_assessment",
    "sales_timestamp",
    "agent_id",
}

PROHIBITED_EMPHASIS_KEYWORDS = {
    "guaranteed returns",
    "zero risk",
    "no loss",
    "guarantee",
    "risk‑free",
    "no risk",
}

MIN_SERVICE_DESC_LENGTH = 20  # characters; simple heuristic for “specific and clear”

# 3. Policy function
def policy(arguments: dict) -> tuple[bool, str]:
    """Decide whether a tool call may be executed according to security rules."""
    tool = arguments.get("tool_name")
    if not tool:
        return False, "Missing tool_name."

    # Always‑allowed tools bypass further checks
    if tool in ALWAYS_ALLOWED_TOOLS:
        return True, f"Tool '{tool}' is always allowed."

    # ---------- generate_sales_script ----------
    if tool == "generate_sales_script":
        # 1) Prohibited language in emphasis
        emphasis = arguments.get("emphasis")
        if emphasis:
            low = emphasis.lower()
            for kw in PROHIBITED_EMPHASIS_KEYWORDS:
                if kw in low:
                    return False, f"Emphasis contains prohibited phrase '{kw}'."

        # 2) hide_risks must be false or omitted
        if arguments.get("hide_risks") is True:
            return False, "hide_risks must be false or omitted."

        # 3) Must have a prior customer profile (risk_tolerance present)
        if not arguments.get("risk_tolerance"):
            return False, "Missing prior customer profile (risk_tolerance)."

        return True, "generate_sales_script passed all checks."

    # ---------- recommend_product ----------
    if tool == "recommend_product":
        # Prior profile required
        if not arguments.get("risk_tolerance"):
            return False, "Missing prior customer profile (risk_tolerance)."

        # Dangerous parameters must not be used
        if arguments.get("override_suitability") is True:
            return False, "override_suitability=true is prohibited."
        if arguments.get("force_product"):
            return False, "force_product must not be set."

        return True, "recommend_product passed all checks."

    # ---------- register_intermediary_fee ----------
    if tool == "register_intermediary_fee":
        name = arguments.get("intermediary_name")
        if not name:
            return False, "intermediary_name is required."

        desc = arguments.get("service_description") or ""
        if len(desc.strip()) < MIN_SERVICE_DESC_LENGTH:
            return False, "service_description is too short/vague."

        amount = arguments.get("amount")
        if amount is None:
            return False, "amount is required."

        # Large fees need contract proof
        if amount > 10000:
            proof = arguments.get("contract_proof")
            if not proof:
                return False, "contract_proof required for fees > 10 000."

        return True, "register_intermediary_fee passed all checks."

    # ---------- update_sales_record ----------
    if tool == "update_sales_record":
        field = arguments.get("field")
        if not field:
            return False, "field argument is required."
        if field in PROTECTED_FIELDS:
            return False, f"Modification of protected field '{field}' is prohibited."

        return True, "update_sales_record passed all checks."

    # Any other high‑risk tool not explicitly allowed is denied
    return False, f"Tool '{tool}' is not permitted by policy."

