import pytest
from policy_under_test import policy

def allowed(args):
    """Helper that returns only the boolean decision from the policy."""
    decision, _ = policy(args)
    return decision

def denied(args):
    """Helper that returns the negated boolean decision from the policy."""
    decision, _ = policy(args)
    return not decision


# ----------------------------------------------------------------------
# Always‑allowed tools
# ----------------------------------------------------------------------
@pytest.mark.parametrize(
    "tool,params",
    [
        ("analyze_customer_profile", {"customer_id": "C123"}),
        ("query_product_info", {}),  # no required params
        ("check_agent_license", {"agent_id": "A456"}),
        ("calculate_commission", {"policy_id": "P1", "agent_id": "A1", "premium": 1000.0, "product_id": "PRD"}),
    ],
)
def test_always_allowed_tools_success(tool, params):
    args = {"tool_name": tool, **params}
    assert allowed(args)


@pytest.mark.parametrize(
    "tool,missing_param",
    [
        ("analyze_customer_profile", "customer_id"),
        ("check_agent_license", "agent_id"),
        ("calculate_commission", "policy_id"),
        ("calculate_commission", "agent_id"),
        ("calculate_commission", "premium"),
        ("calculate_commission", "product_id"),
    ],
)
def test_always_allowed_tools_missing_required(tool, missing_param):
    base = {
        "analyze_customer_profile": {"customer_id": "C123"},
        "check_agent_license": {"agent_id": "A456"},
        "calculate_commission": {
            "policy_id": "P1",
            "agent_id": "A1",
            "premium": 1000.0,
            "product_id": "PRD",
        },
    }[tool]
    base.pop(missing_param, None)
    args = {"tool_name": tool, **base}
    assert denied(args)


